const binaryCache=new Map();
function binary(value){if(binaryCache.has(value))return binaryCache.get(value);const raw=atob(value);const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));binaryCache.set(value,bytes);return bytes}
export const BUNDLED_ASSET_PATHS=Object.freeze(Object.keys(ASSETS));
export async function fetchBundledAsset(request){const method=String(request.method||'GET').toUpperCase();if(!['GET','HEAD'].includes(method))return new Response('method_not_allowed',{status:405});const pathname=new URL(request.url).pathname;const asset=ASSETS[pathname];if(!asset)return new Response('not_found',{status:404,headers:{'cache-control':'no-store'}});const headers={'content-type':asset.type,'x-content-type-options':'nosniff','etag':'"'+asset.sha256+'"','cache-control':asset.type.startsWith('text/html')?'no-store':'public, max-age=3600'};return new Response(method==='HEAD'?null:(asset.text??binary(asset.base64)),{status:200,headers})}
